"""Migrated Meridian CRM opportunity_pipeline workflow."""

from typing import Any


def _numeric(value: Any) -> float:
    """Apply the relevant VRL numeric coercion rules."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _has_lost_reason(record: dict) -> bool:
    """VRL: LOST_RSN <> '' is true only for a non-empty string."""
    return isinstance(record.get("LOST_RSN", ""), str) and record.get("LOST_RSN", "") != ""


def _has_close_date(record: dict) -> bool:
    """VRL explicit inequality against the no-value date sentinel."""
    return str(record.get("CLOSE_DT", "")) != "00000000"


def fire(state: str, event: str, record: dict) -> dict:
    """Fire the first matching opportunity pipeline transition."""
    result_record = dict(record)

    matched = False
    next_state = state
    actions: list[tuple[str, str, str]] = []

    if state == "P" and event == "qualify" and _numeric(record.get("AMT", 0)) > 0:
        matched = True
        next_state = "Q"
        actions = [
            ("set", "STAGE_PCT", "25"),
            ("audit", "OPP_QUAL", ""),
        ]
    elif state == "Q" and event == "advance":
        matched = True
        next_state = "N"
        actions = [
            ("set", "STAGE_PCT", "60"),
        ]
    elif state == "N" and event == "close_won" and _has_close_date(record):
        matched = True
        next_state = "W"
        actions = [
            ("set", "STAGE_PCT", "100"),
            ("audit", "OPP_WON", ""),
            ("notify", "won_deal", ""),
        ]
    elif state == "P" and event == "close_lost" and _has_lost_reason(record):
        matched = True
        next_state = "L"
        actions = [
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST", ""),
        ]
    elif state == "Q" and event == "close_lost" and _has_lost_reason(record):
        matched = True
        next_state = "L"
        actions = [
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST", ""),
        ]
    elif state == "N" and event == "close_lost" and _has_lost_reason(record):
        matched = True
        next_state = "L"
        actions = [
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST", ""),
        ]

    if not matched:
        return {
            "state": state,
            "record": result_record,
            "audits": ["WF_NOMATCH"],
            "notifies": [],
            "matched": False,
        }

    audits: list[str] = []
    notifies: list[str] = []

    for action_type, value, extra in actions:
        if action_type == "set":
            result_record[value] = extra
        elif action_type == "audit":
            audits.append(value)
        elif action_type == "notify":
            notifies.append(value)

    return {
        "state": next_state,
        "record": result_record,
        "audits": audits,
        "notifies": notifies,
        "matched": True,
    }
